def signature_base_string(http_method: str, base_str_uri: str,
    normalized_encoded_request_parameters: str) ->str:
    return '&'.join([
        utils.escape(http_method.upper()),
        utils.escape(base_str_uri),
        utils.escape(normalized_encoded_request_parameters)
    ])

def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')
    uri = uri.strip()
    parsed = urlparse.urlparse(uri)
    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()
    if host is not None:
        netloc = host
    else:
        netloc = parsed.netloc
    netloc = netloc.lower() if netloc else ''
    if not netloc or netloc == ':':
        raise ValueError('uri has no host')
    if netloc.startswith('['):
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        host_part = netloc[:bracket_end + 1]
        rest = netloc[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
    else:
        if ':' in netloc:
            parts = netloc.rsplit(':', 1)
            host_part = parts[0]
            port_str = parts[1]
        else:
            host_part = netloc
            port_str = None
    if not host_part:
        raise ValueError('uri has no host')
    if port_str is not None:
        if port_str == '':
            port = None
        else:
            port_str_stripped = port_str.strip()
            if port_str_stripped == '':
                raise ValueError('invalid port')
            try:
                port = int(port_str_stripped)
            except ValueError:
                raise ValueError('invalid port: ' + port_str)
            if port <= 0 or port > 65535:
                raise ValueError('invalid port number: ' + str(port))
    else:
        port = None
    default_ports = {'http': 80, 'https': 443}
    default_port = default_ports.get(scheme)
    if port is not None and port != default_port:
        netloc = host_part + ':' + str(port)
    else:
        netloc = host_part
    path = parsed.path
    if not path:
        path = '/'
    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')
    netloc = urlparse.quote(netloc, safe='[]:-._~!$&\'()*+,;=@%')
    result = scheme + '://' + netloc + path
    return result

def normalize_parameters(params) ->str:
    if not params:
        return ''
    encoded = []
    for k, v in params:
        encoded.append((utils.escape(k), utils.escape(v)))
    encoded.sort()
    return '&'.join([k + '=' + v for k, v in encoded])

def _sign_hmac(hash_algorithm_name: str, sig_base_str: str, client_secret:
    str, resource_owner_secret: str):
    key = utils.escape(client_secret or '') + '&' + utils.escape(resource_owner_secret or '')
    hash_alg_map = {
        'SHA-1': hashlib.sha1,
        'SHA-256': hashlib.sha256,
        'SHA-512': hashlib.sha512,
    }
    hash_alg = hash_alg_map[hash_algorithm_name]
    key_bytes = key.encode('ascii')
    msg_bytes = sig_base_str.encode('ascii')
    signature = hmac.new(key_bytes, msg_bytes, hash_alg)
    return binascii.b2a_base64(signature.digest())[:-1].decode('ascii')

def _verify_hmac(hash_algorithm_name: str, request, client_secret=None,
    resource_owner_secret=None):
    try:
        norm_params = normalize_parameters(request.params)
        bs_uri = base_string_uri(request.uri)
        sig_base_str = signature_base_string(request.http_method, bs_uri, norm_params)
        signature = _sign_hmac(hash_algorithm_name, sig_base_str, client_secret, resource_owner_secret)
        match = safe_string_equals(signature, request.signature)
        if not match:
            log.debug('Verify HMAC-%s failed', hash_algorithm_name)
        return match
    except Exception:
        return False
